package com.lbos.commercecustomer.service;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.lbos.commercecustomer.client.OrderLogisticsClient;import com.lbos.commercecustomer.dto.client.order.ReviewEligibilityResponse;import com.lbos.commercecustomer.dto.request.ReviewRequest;import com.lbos.commercecustomer.entity.*;import com.lbos.commercecustomer.exception.*;import com.lbos.commercecustomer.mapper.CommerceMapper;import com.lbos.commercecustomer.repository.*;import com.lbos.commercecustomer.service.impl.*;import java.util.*;import org.junit.jupiter.api.Test;class ReviewServiceImplTest{@Test void ineligibleRejected(){var c=mock(ContextSupport.class);var customer=new CustomerProfile();customer.setId(UUID.randomUUID());when(c.customer()).thenReturn(customer);var o=mock(OrderLogisticsClient.class);when(o.reviewEligibility(anyLong(),any(),anyLong())).thenReturn(new ReviewEligibilityResponse(false,1L,customer.getId(),2L,"NO_PURCHASE"));var s=new ReviewServiceImpl(mock(CustomerReviewRepository.class),mock(ProductRepository.class),c,o,new CommerceMapper(),new FeignCallSupport());assertThrows(ForbiddenOperationException.class,()->s.create(new ReviewRequest(1L,2L,(short)5,"Good")));}@Test void ratingBoundaryOneAndFiveAcceptedByDto(){assertEquals((short)1,new ReviewRequest(1L,2L,(short)1,"x").rating());assertEquals((short)5,new ReviewRequest(1L,2L,(short)5,"x").rating());}}